-- Create security definer function to check user roles
CREATE OR REPLACE FUNCTION before.has_role(_user_id UUID, _role app_role)
RETURNS BOOLEAN
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = before
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM before.user_roles
    WHERE user_id = _user_id
      AND role = _role
  )
$$;

-- Create function to check if user is healthcare provider
CREATE OR REPLACE FUNCTION before.is_healthcare_provider(_user_id UUID)
RETURNS BOOLEAN
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = before
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM before.user_roles
    WHERE user_id = _user_id
      AND role IN ('admin', 'doctor', 'staff')
  )
$$;

